            if board[r][c]==king:
                kr,kc=r,c
                break
        if kr is not None: break
    if kr is None: return False
    by_white = (turn == 'b')
    # pawn attacks
    if by_white:
        for dc in (-1,1):
            rr,cc=kr+1,kc+dc
            if 0<=rr<8 and 0<=cc<8 and board[rr][cc]=='P': return True
    else:
        for dc in (-1,1):
            rr,cc=kr-1,kc+dc
            if 0<=rr<8 and 0<=cc<8 and board[rr][cc]=='p': return True
    # knights
    for dr,dc in [(1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)]:
        rr,cc=kr+dr,kc+dc
        if 0<=rr<8 and 0<=cc<8:
            p=board[rr][cc]
            if by_white and p=='N': return True
            if (not by_white) and p=='n': return True
    # kings
